// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type CodeInputAnimationProps = Record<string, any>;

const CodeInputAnimation: React.FC<CodeInputAnimationProps> = ({
  backgroundColor = "#E2E4E9",
  transparentBackground = false,
  durationInSeconds = 5,
  titleText = "Enter your 4-digit code",
  textColor = "#2C3338",
  boxColor = "#F0F1F4",
  dotColor = "#2C3338",
  typingStartDelayFrames = 40,
  framesBetweenKeystrokes = 15,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global entrance animation
  const containerOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });
  const containerY = interpolate(frame, [0, 20], [50, 0], { extrapolateRight: "clamp" });

  const numDigits = 4;
  const digits = Array.from({ length: numDigits });

  // Responsive sizing
  const minDimension = Math.min(width, height);
  const boxSize = minDimension * 0.22;
  const gap = minDimension * 0.04;
  const borderRadius = boxSize * 0.15;
  const dotSize = boxSize * 0.25;
  const fontSize = minDimension * 0.07;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          opacity: containerOpacity,
          transform: `translateY(${containerY}px)`,
          transition: "none",
        }}
      >
        <h1
          style={{
            color: textColor,
            fontSize: `${fontSize}px`,
            fontWeight: 600,
            margin: 0,
            marginBottom: `${minDimension * 0.08}px`,
            letterSpacing: "-0.02em",
            transition: "none",
          }}
        >
          {titleText}
        </h1>

        <div
          style={{
            display: "flex",
            flexDirection: "row",
            gap: `${gap}px`,
            transition: "none",
          }}
        >
          {digits.map((_, index) => {
            // Calculate timing for this specific box's dot
            const inputTriggerFrame = typingStartDelayFrames + index * framesBetweenKeystrokes;
            
            // Dot spring animation (scale from 0 to 1 when typed)
            const dotScale = spring({
              frame: frame - inputTriggerFrame,
              fps,
              config: {
                damping: 12,
                stiffness: 200,
                mass: 0.8,
              },
            });

            // Box "pop" animation when filled
            const boxPopSpring = spring({
              frame: frame - inputTriggerFrame,
              fps,
              config: {
                damping: 8,
                stiffness: 300,
                mass: 0.5,
              },
            });
            // Map the spring (0->1) to a scale bump (1 -> 1.05 -> 1)
            const boxScale = interpolate(boxPopSpring, [0, 0.5, 1], [1, 1.05, 1], { extrapolateRight: "clamp" });

            return (
              <div
                key={index}
                style={{
                  width: `${boxSize}px`,
                  height: `${boxSize * 1.2}px`,
                  backgroundColor: boxColor,
                  borderRadius: `${borderRadius}px`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  boxShadow: "inset 0px 2px 4px rgba(0,0,0,0.02)",
                  transform: `scale(${boxScale})`,
                  transition: "none",
                }}
              >
                {frame >= inputTriggerFrame && (
                  <div
                    style={{
                      width: `${dotSize}px`,
                      height: `${dotSize}px`,
                      backgroundColor: dotColor,
                      borderRadius: "50%",
                      transform: `scale(${dotScale})`,
                      transition: "none",
                    }}
                  />
                )}
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CodeInputAnimation;